package dev.patienty.assistant;import dev.patienty.assistant.AssistantDtos.*;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/patients/{patientId}/ai/queries")public class PatientAssistantController{private final PatientAssistantService service;public PatientAssistantController(PatientAssistantService service){this.service=service;}@PostMapping public AiQueryResponse ask(@PathVariable UUID patientId,@Valid@RequestBody AiQueryRequest request){return service.answer(patientId,request.question().trim());}}
